local function normalize(value)
    return string.lower(tostring(value or ""))
        :gsub("^%s+", "")
        :gsub("%s+$", "")
        :gsub("[_%s]+", "-")
        :gsub("%-+", "-")
end

function Catalog.Normalize(value)
    return normalize(value)
end

function Catalog.ResolveName(value, fallbackTitle)
    local raw = tostring(value or "")
    if string.sub(raw, 1, 13) == "rbxassetid://" then
        return nil, raw
    end

    local key = normalize(raw)
    if Catalog.Icons[key] then
        return key, Catalog.Icons[key]
    end

    local alias = Catalog.Aliases[key]
    if alias and Catalog.Icons[alias] then
        return alias, Catalog.Icons[alias]
    end

    local fallbackKey = normalize(fallbackTitle)
    local fallbackAlias = Catalog.Aliases[fallbackKey] or fallbackKey
    if Catalog.Icons[fallbackAlias] then
        return fallbackAlias, Catalog.Icons[fallbackAlias]
    end

    return Catalog.Fallback, Catalog.Icons[Catalog.Fallback]
end

function Catalog.Resolve(value, fallbackTitle)
    local _, asset = Catalog.ResolveName(value, fallbackTitle)
    return asset
end

function Catalog.Has(value)
    local key = normalize(value)
    return Catalog.Icons[key] ~= nil
end

return Catalog
end)()

-- MODULE: core/State.lua
M.State = (function()
-- Prototype-only settings. Never reads/writes production Serenity config.
local State={}; State.__index=State
local function copy(v)
    if type(v)~='table' then return v end
    local out={}; for k,x in pairs(v) do out[k]=copy(x) end; return out
end
function State.new(defaults, runtime, path)
    local self=setmetatable({Data=copy(defaults), Defaults=copy(defaults), Runtime=runtime, Revision=0,
        Path=path or 'SerenityConcept02/settings-v1.json', FileAPI=type(readfile)=='function' and type(writefile)=='function' and type(isfile)=='function'},State)
    if self.FileAPI then
        local ok,decoded=pcall(function()
            if isfile(self.Path) then return game:GetService('HttpService'):JSONDecode(readfile(self.Path)) end
        end)
        if ok and type(decoded)=='table' and decoded.Schema==1 and type(decoded.Values)=='table' then
            for key,default in pairs(defaults) do
                if type(decoded.Values[key])==type(default) then self.Data[key]=copy(decoded.Values[key]) end
            end
        end
    end
    runtime:OnDestroy(function() self:Save() end)
    return self
end
function State:Get(key, fallback)
    if self.Data[key]==nil then return copy(fallback) end
    return copy(self.Data[key])
end
function State:Set(key,value)
    self.Data[key]=copy(value); self.Revision=self.Revision+1
    local revision=self.Revision
    task.delay(0.55,function() if not self.Runtime.Destroyed and revision==self.Revision then self:Save() end end)
end
function State:Save()
    if not self.FileAPI then return false end
    return pcall(function()
        if type(makefolder)=='function' then pcall(makefolder,'SerenityConcept02');pcall(makefolder,'SerenityHub') end
        writefile(self.Path,game:GetService('HttpService'):JSONEncode({Schema=1,Values=self.Data}))
    end)
end
return State
end)()

-- MODULE: core/UI.lua
M.UI = (function()
return function(theme, runtime, icons)
    local UI={T=theme,R=runtime,AccentBindings={},Reduced=false,ScaleFactor=1,LayoutCallbacks={}}
    function UI:New(kind,parent,props)
        local object=Instance.new(kind)
        for key,value in pairs(props or {}) do object[key]=value end
        object.Parent=parent
        if self.Locale and (kind=='TextLabel' or kind=='TextButton' or kind=='TextBox') then
            object.AutoLocalize=false
            if kind=='TextBox' then self.Locale:Bind(object,'PlaceholderText')
            else self.Locale:Bind(object,'Text') end
        end
        return object
    end
    function UI:Frame(parent,props)
        local f=self:New('Frame',parent,{BorderSizePixel=0,BackgroundTransparency=1})
        for k,v in pairs(props or {}) do f[k]=v end; return f
    end
    function UI:Round(parent,radius) return self:New('UICorner',parent,{CornerRadius=UDim.new(0,radius or 8)}) end
    function UI:Stroke(parent,color,transparency)
        return self:New('UIStroke',parent,{Color=color or theme.Line,Thickness=1,Transparency=transparency or 0.3,ApplyStrokeMode=Enum.ApplyStrokeMode.Border})
    end
    function UI:Panel(parent,props)
        local f=self:Frame(parent,{BackgroundColor3=theme.Panel,BackgroundTransparency=0})
        for k,v in pairs(props or {}) do f[k]=v end
        self:Round(f,10); self:Stroke(f); return f
    end
    function UI:Label(parent,text,size,pos,dimensions,color,bold)
        return self:New('TextLabel',parent,{Text=text,Font=bold and theme.Bold or theme.Medium,TextSize=size or 13,
            TextColor3=color or theme.Text,BackgroundTransparency=1,Position=pos or UDim2.new(),Size=dimensions or UDim2.fromScale(1,1),
            TextXAlignment=Enum.TextXAlignment.Left,TextTruncate=Enum.TextTruncate.AtEnd})
    end
    function UI:RawLabel(...)
        local locale=self.Locale;self.Locale=nil
        local label=self:Label(...);self.Locale=locale
        return label
    end
    function UI:Icon(parent,name,size,pos,color)
        return self:New('ImageLabel',parent,{BackgroundTransparency=1,Image=icons.Resolve(name),ImageColor3=color or theme.Muted,
            ScaleType=Enum.ScaleType.Fit,Size=UDim2.fromOffset(size or 16,size or 16),Position=pos or UDim2.new()})
    end
    function UI:Button(parent,text,props,callback)
        local b=self:New('TextButton',parent,{Text=text or '',Font=theme.Medium,TextSize=12,TextColor3=theme.Text,
            BorderSizePixel=0,AutoButtonColor=false,BackgroundColor3=theme.Inset,Size=UDim2.fromOffset(100,30)})
        for k,v in pairs(props or {}) do b[k]=v end
        self:Round(b,7)
        local feedback=self:New('UIStroke',b,{Color=theme.Text,Thickness=1,Transparency=1,ApplyStrokeMode=Enum.ApplyStrokeMode.Border})
        local hovering=false
        local function highlight(value) if not runtime.Destroyed and not self.Touch and not self.LowEffects then self:Tween(feedback,0.1,{Transparency=value}) end end
        b.MouseEnter:Connect(function() hovering=true; highlight(0.78) end)
        b.MouseLeave:Connect(function() hovering=false; highlight(1) end)
        b.InputBegan:Connect(function(event)
            if event.UserInputType==Enum.UserInputType.MouseButton1 or event.UserInputType==Enum.UserInputType.Touch then highlight(0.5) end
        end)
        b.InputEnded:Connect(function(event)
            if event.UserInputType==Enum.UserInputType.MouseButton1 or event.UserInputType==Enum.UserInputType.Touch then highlight(hovering and 0.78 or 1) end
        end)
        if callback then b.Activated:Connect(function() if not runtime.Destroyed then callback() end end) end
        return b
    end
    function UI:List(parent,gap,horizontal)
        return self:New('UIListLayout',parent,{Padding=UDim.new(0,gap or 0),SortOrder=Enum.SortOrder.LayoutOrder,
            FillDirection=horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical})
    end
    function UI:Pad(parent,left,top,right,bottom)
        self:New('UIPadding',parent,{PaddingLeft=UDim.new(0,left),PaddingTop=UDim.new(0,top or left),
            PaddingRight=UDim.new(0,right or left),PaddingBottom=UDim.new(0,bottom or top or left)})
    end
    function UI:Accent(callback)
        self.AccentBindings[#self.AccentBindings+1]=callback; callback(theme.Accent)
    end
    function UI:SetAccent(color)
        theme.Accent=color
        for _,fn in ipairs(self.AccentBindings) do fn(color) end
    end
    function UI:Tween(object,time,props,completed) return runtime:Tween(object,time,props,self.Reduced or self.LowEffects,completed) end
    function UI:Row(parent,title,height)
        local row=self:Frame(parent,{Size=UDim2.new(1,0,0,math.max(height or 44,self.Touch and 48 or 44))})
        local label=self:Label(row,title,13,UDim2.fromOffset(12,0),UDim2.new(0.5,-18,1,0))
        self:Frame(row,{Position=UDim2.new(0,12,1,-1),Size=UDim2.new(1,-24,0,1),BackgroundColor3=theme.Line,BackgroundTransparency=0.65})
        return row,label
    end
    return UI
end
end)()

-- MODULE: core/Input.lua
M.Input = (function()
return function(runtime)
    local service=game:GetService('UserInputService')
    local input={Drag=nil,Shortcuts={},Service=service}
    function input:Cancel()
        local drag=self.Drag; self.Drag=nil
        if drag and drag.Finish then drag.Finish() end
    end
    function input:Capture(source,onMove,onEnd)
        self:Cancel()
        self.Drag={Source=source,Move=onMove,Finish=onEnd}; onMove(source.Position)
    end
    runtime:Connect(service.InputChanged,function(event)
        local drag=input.Drag
        if drag and (event==drag.Source or (drag.Source.UserInputType==Enum.UserInputType.MouseButton1 and event.UserInputType==Enum.UserInputType.MouseMovement)) then drag.Move(event.Position) end
    end)
    runtime:Connect(service.InputEnded,function(event)
        local drag=input.Drag
        if drag and (event==drag.Source or (drag.Source.UserInputType==Enum.UserInputType.MouseButton1 and event.UserInputType==Enum.UserInputType.MouseButton1)) then
            input.Drag=nil; if drag.Finish then drag.Finish() end
        end
    end)
    runtime:Connect(service.InputBegan,function(event,processed)
        if (processed or service:GetFocusedTextBox()) and event.KeyCode~=Enum.KeyCode.Escape then return end
        for _,fn in ipairs(input.Shortcuts) do if fn(event,service) then break end end
    end)
    runtime:OnDestroy(function() input:Cancel() end)
    return input
end
end)()

-- MODULE: core/Assets.lua
M.Assets = (function()
return function(runtime,options)
    local Assets={}
    local names={Community='community-v1.png',Updates='updates-v1.png',Discord='discord-v1.png'}
    local custom=getcustomasset or getsynasset
    local function validPNG(bytes) return type(bytes)=='string' and #bytes<12000000 and bytes:sub(1,8)=='\137PNG\13\10\26\10' end
    function Assets:Load(kind,label)
        local override=options[kind..'Image']
        if type(override)=='string' and override:match('^rbxassetid://%d+$') then label.Image=override; return end
        if type(custom)~='function' or type(writefile)~='function' or type(isfile)~='function' or type(readfile)~='function' then return end
        task.spawn(function()
            local ok,asset=pcall(function()
                local folder='SerenityConcept02'
                if type(makefolder)=='function' then pcall(makefolder,folder) end
                local path=folder..'/'..names[kind]
                local bytes
                if isfile(path) then bytes=readfile(path) end
                if not validPNG(bytes) then
                    bytes=kind=='Discord' and options.DiscordBytes or game:HttpGet(options.AssetBase..names[kind])
                    assert(validPNG(bytes),'Invalid banner response')
                    writefile(path,bytes)
                end
                return custom(path)
            end)
            if ok and type(asset)=='string' and not runtime.Destroyed and label.Parent then label.Image=asset end
        end)
    end
    return Assets
end
end)()

-- MODULE: core/Popup.lua
M.Popup = (function()
return function(ui,input,screen,getScale)
    local Popup={Active=nil,Owner=nil,Closing=nil,Panel=nil}
    function Popup:Discard(root)
        if not root then return end
        local function cancel(object)
            ui.R:CancelTween(object)
            for _,child in ipairs(object:GetChildren()) do cancel(child) end
        end
        cancel(root)
        root:Destroy()
    end
    function Popup:Close(instant)
        if self.OnClose then self.OnClose(); self.OnClose=nil end
        self:Discard(self.Closing); self.Closing=nil
        local root,panel=self.Active,self.Panel
        local focused=input.Service:GetFocusedTextBox()
        if focused and root and focused:IsDescendantOf(root) then focused:ReleaseFocus() end
        self.Active=nil; self.Owner=nil; self.Panel=nil
        if not root then return end
        if instant or ui.R.Destroyed or ui.Reduced or ui.LowEffects then self:Discard(root); return end
        self.Closing=root
        ui:Tween(panel,0.12,{GroupTransparency=1},function()
            if self.Closing==root then self.Closing=nil; self:Discard(root) end
        end)
    end
    function Popup:Open(owner,width,height,anchor)
        self:Close(true); input:Cancel()
        local root=ui:Frame(screen,{Size=UDim2.fromScale(1,1),ZIndex=100})
        self.Active=root; self.Owner=owner
        local shield=ui:Button(root,'',{Size=UDim2.fromScale(1,1),BackgroundTransparency=1,ZIndex=1},function() self:Close() end)
        local view=screen.AbsoluteSize
        local scale=math.min(getScale(),(view.X-20)/width,(view.Y-20)/height)
        scale=math.max(0.2,scale)
        local x,y=(view.X-width*scale)/2,(view.Y-height*scale)/2
        if anchor then
            x=anchor.AbsolutePosition.X+anchor.AbsoluteSize.X-width*scale
            y=anchor.AbsolutePosition.Y+anchor.AbsoluteSize.Y+5
            if y+height*scale>view.Y-10 then y=anchor.AbsolutePosition.Y-height*scale-5 end
        end
        x=math.clamp(x,10,math.max(10,view.X-width*scale-10))
        y=math.clamp(y,10,math.max(10,view.Y-height*scale-10))
        local panel=ui:New(ui.LowEffects and 'Frame' or 'CanvasGroup',root,{BackgroundTransparency=0,BorderSizePixel=0,Size=UDim2.fromOffset(width,height),Position=UDim2.fromOffset(x,y),ZIndex=2,Active=true})
        ui:New('UIScale',panel,{Scale=scale})
        panel.BackgroundColor3=Color3.fromRGB(19,19,24)
        ui:Round(panel,10)
        self.Panel=panel
        panel.Position=UDim2.fromOffset(x,y+(ui.Reduced and 0 or 6))
        if not ui.LowEffects then
            panel.GroupTransparency=ui.Reduced and 0 or 1
            ui:Tween(panel,0.16,{GroupTransparency=0,Position=UDim2.fromOffset(x,y)})
        else panel.Position=UDim2.fromOffset(x,y) end
        return panel
    end
    function Popup:Message(title,message,link)
        local panel=self:Open(nil,380,link and 236 or 210)
        ui:Label(panel,title,16,UDim2.fromOffset(18,14),UDim2.new(1,-36,0,28),nil,true)
        local body=ui:Label(panel,message,12,UDim2.fromOffset(18,51),UDim2.new(1,-36,0,100),ui.T.Muted)
        body.TextWrapped=true; body.TextTruncate=Enum.TextTruncate.None; body.TextYAlignment=Enum.TextYAlignment.Top
        if link then
            local box=ui:New('TextBox',panel,{Position=UDim2.fromOffset(18,148),Size=UDim2.new(1,-36,0,30),Text=link,ClearTextOnFocus=false,
                TextSize=11,Font=ui.T.Font,TextColor3=ui.T.Text,BackgroundColor3=ui.T.Inset,BorderSizePixel=0})
            ui:Round(box,6)
        end
        ui:Button(panel,'Close',{AnchorPoint=Vector2.new(1,1),Position=UDim2.new(1,-18,1,-16),Size=UDim2.fromOffset(80,30)},function() self:Close() end)
    end
    ui.R:OnDestroy(function() Popup:Close() end)
    table.insert(input.Shortcuts,function(event) if event.KeyCode==Enum.KeyCode.Escape and Popup.Active then Popup:Close(); return true end end)
    return Popup
end
end)()

-- MODULE: components/Section.lua
M.Section = (function()
return function(ui,parent,title,open,onOpen)
    local root=ui:Panel(parent,{Size=UDim2.new(1,0,0,44),ClipsDescendants=true})
    local head=ui:Button(root,'',{Size=UDim2.new(1,0,0,44),BackgroundTransparency=1})
    ui:Label(head,title,13,UDim2.fromOffset(12,0),UDim2.new(1,-45,1,0),ui.T.Text,true)
    local accent=ui:Frame(head,{Position=UDim2.new(0,12,1,-1),Size=UDim2.new(1,-24,0,1),BackgroundColor3=ui.T.Accent,BackgroundTransparency=0.35})
    ui:Accent(function(color) accent.BackgroundColor3=color end)
    local caret=ui:Icon(head,'chevron-down',18,UDim2.new(1,-30,0,13))
    local body=ui:Frame(root,{Position=UDim2.fromOffset(0,44),Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y})
    local list=ui:List(body,0)
    local section={Frame=root,Body=body,Open=open~=false,Revision=0}
    local function size(animate)
        ui:Tween(caret,animate and 0.18 or 0,{Rotation=section.Open and 180 or 0})
        -- All control rows have explicit logical heights. Avoid scale-dependent layout measurements.
        local height=5
        for _,child in ipairs(body:GetChildren()) do
            if child:IsA('Frame') and child.Visible then height=height+child.Size.Y.Offset end
        end
        local target=44+(section.Open and height or 0)
        ui:Tween(root,animate and 0.18 or 0,{Size=UDim2.new(1,0,0,target)})
    end
    function section:SetOpen(value,instant)
        self.Open=value==true; size(not instant)
        if onOpen then onOpen(self.Open) end
    end
    ui.R:Connect(head.Activated,function() section:SetOpen(not section.Open) end)
    ui.R:Connect(list:GetPropertyChangedSignal('AbsoluteContentSize'),function() size(false) end)
    table.insert(ui.LayoutCallbacks,function() size(false) end)
    size(false)
    task.defer(function() if not ui.R.Destroyed then size(false) end end)
    return section
end
end)()

-- MODULE: components/Feedback.lua
M.Feedback = (function()
-- Shared, user-submitted reports. No automatic collection or startup sends.
return function(ui,app,parent,options,choice)
    local service=game:GetService('HttpService')
    local relay=options.FeedbackRelay or ((getgenv and getgenv()) or _G).SerenityFeedbackRelay
    if type(relay)~='string' or not relay:match('^https://[%w%.%-]+/') then relay=nil end
    -- Owner-approved public reporting destination. Shared across PC/mobile; not profile data.
    local defaultEndpoint='https://discord.com/api/webhooks/1546188887808938128/TXP6NrlEBnS9HX4lZLRb0_UEUkd8cEJgr-BXz-fOpQ5-O6GuAaV0DiAYSDHQXESydyoo'
    local function valid(url) return type(url)=='string' and url:match('^https://discord%.com/api/webhooks/%d+/[%w_%-]+$')~=nil end
    local endpoint=options.FeedbackWebhook or ((getgenv and getgenv()) or _G).SerenityFeedbackWebhook
    if not valid(endpoint) then endpoint=defaultEndpoint end
    local function length(text) return utf8.len(text) or #text end
    local scroll=ui:New('ScrollingFrame',parent,{Size=UDim2.fromScale(1,1),BackgroundTransparency=1,BorderSizePixel=0,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,ScrollBarThickness=3})
    ui:List(scroll,10);ui:Pad(scroll,2,2,6,10)
    local function field(title,height)
        local row=ui:Panel(scroll,{Size=UDim2.new(1,0,0,height)})
        ui:Label(row,title,13,UDim2.fromOffset(12,6),UDim2.new(1,-24,0,24),nil,true)
        return row
    end
    local category=choice(scroll,{Title='Report type',Options={'Bug Report','Feedback','New Feature','New Game Request'},Default='Bug Report'},false)
    local draft=field('Bug report or feedback',202)
    local box=ui:New('TextBox',draft,{Position=UDim2.fromOffset(12,36),Size=UDim2.new(1,-24,0,128),Text='',PlaceholderText='What happened? What did you expect? Include steps to reproduce.',MultiLine=true,TextWrapped=true,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,ClearTextOnFocus=false,Font=ui.T.Font,TextSize=13,TextColor3=ui.T.Text,BackgroundColor3=ui.T.Inset,BorderSizePixel=0})
    ui:Round(box,6);ui:Pad(box,8)
    local count=ui:Label(draft,'0 / 1800 characters',11,UDim2.fromOffset(12,174),UDim2.new(1,-24,0,18),ui.T.Muted)
    ui.R:Connect(box:GetPropertyChangedSignal('Text'),function()
        count.Text=tostring(length(box.Text))..' / 1800 characters'
        count.TextColor3=length(box.Text)>1800 and ui.T.Accent or ui.T.Muted
    end)
    local context=field('Included with your report',108)
    ui:Label(context,'Game: '..tostring(options.Manifest and options.Manifest.GameName or app.GameTitle.Text)..'\nPlace: '..tostring(game.PlaceId)..'\nServer Job ID and preview version. No profile settings.',11,UDim2.fromOffset(12,34),UDim2.new(1,-24,0,66),ui.T.Muted).TextWrapped=true
    local configured=relay or valid(endpoint)
    local status=ui:Label(scroll,configured and 'Sends to Serenity when you press Submit.' or 'Shared reporting is awaiting server setup. Your draft stays here.',12,nil,UDim2.new(1,0,0,36),ui.T.Muted)
    status.TextWrapped=true; status.TextTruncate=Enum.TextTruncate.None
    local busy,last=false,-math.huge
    local button
    local function submit()
        if busy then return end
        if not relay and not valid(endpoint) then status.Text='Serenity’s report server is not connected yet. Your draft is safe.';return end
        local message=box.Text:match('^%s*(.-)%s*$')
        if length(message)<10 or length(message)>1800 then status.Text='Write between 10 and 1800 characters.';return end
        if os.clock()-last<30 then status.Text='Please wait 30 seconds between reports.';return end
        local send
        for _,name in ipairs({'request','http_request'}) do
            local candidate=((getgenv and getgenv()) or _G)[name]
            if type(candidate)=='function' then send=candidate;break end
        end
        send=send or (type(request)=='function' and request) or (type(http_request)=='function' and http_request) or (type(syn)=='table' and type(syn.request)=='function' and syn.request)
        if type(send)~='function' then status.Text='HTTP requests are unavailable on this device.';return end
        busy=true;last=os.clock();button.Text='Sending…';status.Text='Sending your report…'
        local body=service:JSONEncode({allowed_mentions={parse={}},embeds={{title='Serenity · '..category:Get(),description=message,fields={
            {name='Game',value=tostring(options.Manifest and options.Manifest.GameName or app.GameTitle.Text)},
            {name='Place ID',value=tostring(game.PlaceId)},
            {name='Job ID',value=tostring(game.JobId or 'Unavailable')},
            {name='UI build',value='Serenity UI · 3.2.0'},
        }}}})
        task.spawn(function()
            local ok,response=pcall(send,{Url=relay or endpoint,Method='POST',Headers={['Content-Type']='application/json'},Body=body})
            if ui.R.Destroyed then return end
            busy=false;button.Text='Submit report'
            local code=ok and type(response)=='table' and tonumber(response.StatusCode or response.Status)
            if code and code>=200 and code<300 then
                if box.Text:match('^%s*(.-)%s*$')==message then box.Text='' end
                status.Text='Report delivered. Thank you.';app:Notify('Report delivered')
            else
                if code==429 then status.Text='Discord rate limit. Try again later.'
                elseif code==401 or code==403 or code==404 then status.Text='Report destination unavailable. Please tell Serenity staff.'
                else status.Text='Not delivered. Your draft is still here.' end
            end
        end)
    end
    button=ui:Button(scroll,configured and 'Submit report' or 'Reporting unavailable',{Size=UDim2.new(1,0,0,44),BackgroundColor3=ui.T.Accent},submit)
    app.Feedback={Submit=submit,Draft=box,Category=category,Status=status}
end
end)()

-- MODULE: components/Controls.lua
M.Controls = (function()
return function(ui,input,popup)
    local Controls={}
    local function emit(self,silent)
        if not silent and self.Callback then self.Callback(self:Get()) end
    end
    function Controls.Switch(parent,props)
        local row,label=ui:Row(parent,props.Title)
        local track=ui:Frame(row,{Size=UDim2.fromOffset(42,24),Position=UDim2.new(1,-54,0.5,-12),BackgroundTransparency=0})
        ui:Round(track,12)
        local dot=ui:Frame(track,{Size=UDim2.fromOffset(18,18),BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=0})
        ui:Round(dot,10)
        local control={Frame=row,Value=props.Default==true,Enabled=props.Enabled~=false,Callback=props.Callback}
        function control:Get() return self.Value end
        function control:Render(animate)
            track.BackgroundColor3=self.Value and ui.T.Accent or Color3.fromRGB(57,57,68)
            label.TextColor3=self.Enabled and ui.T.Text or ui.T.Dim
            dot.BackgroundTransparency=self.Enabled and 0 or 0.5
            ui:Tween(dot,animate and 0.12 or 0,{Position=UDim2.fromOffset(self.Value and 21 or 3,3)})
        end
        function control:Set(value,silent)
            local old=self.Value; self.Value=value==true; self:Render(true)
            if old~=self.Value then emit(self,silent) end
        end
        function control:SetEnabled(value) self.Enabled=value==true; self:Render(false) end
        ui:Button(row,'',{Size=UDim2.fromScale(1,1),BackgroundTransparency=1},function() if control.Enabled then control:Set(not control.Value) end end)
        ui:Accent(function() control:Render(false) end)
        return control
    end
    function Controls.Slider(parent,props)
        local row,label=ui:Row(parent,props.Title,62)
        label.Size=UDim2.new(0.65,0,0,30)
        local box=ui:New('TextBox',row,{Position=UDim2.new(1,-81,0,2),Size=UDim2.fromOffset(69,27),Text='',ClearTextOnFocus=false,
            Font=ui.T.Medium,TextSize=12,TextColor3=ui.T.Accent,TextXAlignment=Enum.TextXAlignment.Right,BackgroundTransparency=1})
        local bar=ui:Frame(row,{Position=UDim2.fromOffset(12,43),Size=UDim2.new(1,-24,0,5),BackgroundColor3=Color3.fromRGB(42,42,51),BackgroundTransparency=0})
        ui:Round(bar,4)
        local fill=ui:Frame(bar,{Size=UDim2.fromScale(0,1),BackgroundTransparency=0}); ui:Round(fill,4)
        local dot=ui:Frame(bar,{AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0,0.5),Size=UDim2.fromOffset(14,14),BackgroundColor3=ui.T.Text,BackgroundTransparency=0}); ui:Round(dot,8)
        local hit=ui:Button(row,'',{Position=UDim2.fromOffset(6,31),Size=UDim2.new(1,-12,0,28),BackgroundTransparency=1})
        local min,max,step=props.Min or 0,props.Max or 100,props.Step or 1
        assert(max>min and step>0,'Invalid slider bounds')
        local control={Frame=row,Value=min,Enabled=props.Enabled~=false,Callback=props.Callback}
        function control:Get() return self.Value end
        function control:Render()
            local a=(self.Value-min)/(max-min); fill.Size=UDim2.fromScale(a,1); dot.Position=UDim2.fromScale(a,0.5)
            box.Text=string.format('%.4f',self.Value):gsub('0+$',''):gsub('%.$','')..(props.Suffix or '')
            label.TextColor3=self.Enabled and ui.T.Text or ui.T.Dim
        end
        function control:Set(value,silent)
            value=tonumber(value); if not value or value~=value or math.abs(value)==math.huge then self:Render(); return end
            value=math.clamp(min+math.floor((value-min)/step+0.5)*step,min,max)
            local old=self.Value; self.Value=value; self:Render(); if old~=value then emit(self,silent) end
        end
        function control:SetEnabled(value) self.Enabled=value==true; box.TextEditable=self.Enabled; self:Render() end
        ui.R:Connect(hit.InputBegan,function(event)
            if control.Enabled and (event.UserInputType==Enum.UserInputType.MouseButton1 or event.UserInputType==Enum.UserInputType.Touch) then
                input:Cancel()
                local ancestor=row.Parent
                while ancestor and not ancestor:IsA('ScrollingFrame') do ancestor=ancestor.Parent end
                local scrollEnabled=ancestor and ancestor.ScrollingEnabled
                if ancestor then ancestor.ScrollingEnabled=false end
                input:Capture(event,function(pos)
                    local a=math.clamp((pos.X-bar.AbsolutePosition.X)/math.max(1,bar.AbsoluteSize.X),0,1)
                    control:Set(min+a*(max-min))
                end,function() if ancestor and ancestor.Parent then ancestor.ScrollingEnabled=scrollEnabled end end)
            end
        end)
        ui.R:Connect(box.FocusLost,function() if control.Enabled then control:Set(box.Text:match('[-+]?%d*%.?%d+')) else control:Render() end end)
        ui:Accent(function(color) fill.BackgroundColor3=color; box.TextColor3=color end)
        control:Set(props.Default or min,true)
        return control
    end
    function Controls.Input(parent,props)
        local row,label=ui:Row(parent,props.Title,68); label.Size=UDim2.new(1,-24,0,28)
        local box=ui:New('TextBox',row,{Position=UDim2.fromOffset(12,30),Size=UDim2.new(1,-24,0,28),Text='',PlaceholderText=props.Placeholder or '',
            PlaceholderColor3=ui.T.Dim,TextColor3=ui.T.Text,Font=ui.T.Medium,TextSize=11,TextXAlignment=Enum.TextXAlignment.Left,
            ClearTextOnFocus=false,BackgroundColor3=ui.T.Inset,BorderSizePixel=0}); ui:Round(box,6); ui:Pad(box,8,0,8,0)
        local control={Frame=row,Value='',Enabled=props.Enabled~=false,Callback=props.Callback}
        function control:Get() return self.Value end
        function control:Set(value,silent)
            value=tostring(value or ''):sub(1,512); local old=self.Value; self.Value=value; box.Text=value
            if old~=value then emit(self,silent) end
        end
        function control:SetEnabled(value) self.Enabled=value==true; box.TextEditable=self.Enabled end
        ui.R:Connect(box.FocusLost,function() if control.Enabled then control:Set(box.Text) end end)
        control:Set(props.Default,true); return control
    end
    function Controls.Action(parent,props)
        local row,label=ui:Row(parent,props.Title,42); label.Size=UDim2.new(1,-45,1,0)
        ui:Icon(row,props.Icon or 'chevron-right',15,UDim2.new(1,-28,0.5,-7.5))
        local control={Frame=row,Enabled=props.Enabled~=false,Busy=false}
        function control:SetEnabled(value) self.Enabled=value==true; label.TextColor3=self.Enabled and ui.T.Text or ui.T.Dim end
        ui:Button(row,'',{Size=UDim2.fromScale(1,1),BackgroundTransparency=1},function()
            if not control.Enabled or control.Busy then return end
            local function invoke()
                if ui.R.Destroyed then return end
                control.Busy=true
                local ok,err=pcall(function() if props.Callback then props.Callback() end end)
                control.Busy=false
                if not ok then popup:Message('Action unavailable',tostring(err)) end
            end
            if props.Confirm then
                local panel=popup:Open(nil,340,174)
                ui:Label(panel,props.Title or 'Confirm action',15,UDim2.fromOffset(14,10),UDim2.new(1,-28,0,28),nil,true)
                local text=ui:Label(panel,props.ConfirmText or props.Description or 'Proceed with this action?',12,UDim2.fromOffset(14,44),UDim2.new(1,-28,0,65),ui.T.Muted)
                text.TextWrapped=true
                ui:Button(panel,'Cancel',{Position=UDim2.fromOffset(14,122),Size=UDim2.fromOffset(145,40)},function()popup:Close()end)
                ui:Button(panel,'Confirm',{Position=UDim2.fromOffset(177,122),Size=UDim2.fromOffset(145,40)},function()popup:Close();invoke()end)
            else invoke() end
        end)
        return control
    end
    function Controls.Paragraph(parent,props)
        local row=ui:Frame(parent,{Size=UDim2.new(1,0,0,props.Height or 76)})
        local panel=ui:Panel(row,{Position=UDim2.fromOffset(10,6),Size=UDim2.new(1,-20,1,-12),BackgroundColor3=Color3.fromRGB(22,40,52)})
