-- V3 manifest bridge. Game config/lifecycle retain the existing core contracts.
local function copy(v)
    if type(v)~='table' then return v end
    local out={};for k,x in pairs(v)do out[k]=copy(x)end;return out
end
local function visible(node,layout)
    if node.DesktopOnly and layout~='Desktop' then return false end
    if node.MobileOnly and layout~='Mobile' then return false end
    if node.Platforms then
        for _,name in ipairs(node.Platforms)do if name==layout then return true end end
        return false
    end
    return true
end
local function remote(path)
    local fn,err=loadstring(game:HttpGet('https://raw.githubusercontent.com/MUshihara/Serenity-hub/main/'..path..'?serenity=3.2.0'), '@Serenity/'..path)
    if not fn then error(err,0) end
    return fn()
end
