    local runtime=Runtime.new(options.RuntimeKey or source.RuntimeKey or '__SERENITY_RUNTIME_V3')
    local defaults={}
    for _,p in ipairs(source.Pages)do for _,f in ipairs(p.Features or {})do for _,c in ipairs(f.Controls or {})do
        if c.Id and c.Default~=nil then defaults[p.Id..'.'..f.Id..'.'..c.Id]=copy(c.Default) end
    end end end
    local config=Config.new({Defaults=defaults,SchemaVersion=source.ConfigVersion or 1,Migrations=source.ConfigMigrations or {},Path=options.ConfigPath or source.ConfigPath or ('SerenityHub/config-'..tostring(game.GameId)..'.json')})
    runtime:TrackCleanup(function()config:Destroy()end)
    local window,adapter
    local function callback(fn,...)
        if type(fn)~='function' then return end
        local args=table.pack(...)
        task.spawn(function()
            if runtime.Destroyed then return end
            local ok,err=pcall(fn,table.unpack(args,1,args.n))
            if not ok then warn('[SERENITY HUB] Callback failed: '..tostring(err)) end
        end)
    end
    local manifest=copy(source);manifest.Pages={}
    local about=copy(M.Manifest.Pages[1]);about.SharedPreview=true;manifest.Pages[1]=about
    for _,original in ipairs(source.Pages)do
        if visible(original,profile.Layout) then
            local page=copy(original);page.Features={}
            if page.Id=='About' or page.Id=='Settings' or page.Id=='Feedback' then page.Id='Game_'..page.Id end
            if original.Id=='Settings' then page.Title='Game Settings' end
            page.Icon=page.Icon or 'menu'
            for _,originalFeature in ipairs(original.Features or {})do
                if visible(originalFeature,profile.Layout) then
                    local feature=copy(originalFeature);feature.ConfigPage=original.Id;feature.Controls={}
                    for index,originalControl in ipairs(originalFeature.Controls or {})do
                        if visible(originalControl,profile.Layout) then
                            local c=copy(originalControl);c.Id=c.Id or ('Info'..index)
                            local key=original.Id..'.'..originalFeature.Id..'.'..c.Id
                            if c.Value~=nil and (c.Type=='Live' or c.Type=='Progress') then c.Default=c.Value end
                            if c.Type=='Action' then
                                c.Callback=function()
                                    if c.CoreAction=='SaveConfig' then config:SaveNow()
                                    elseif c.CoreAction=='ResetConfig' then adapter:ResetAll()
                                    else callback(originalControl.Callback,window,adapter) end
                                end
                            else
                                c.Changed=function(value)
                                    config:Set(key,value,false)
                                    callback(originalControl.Changed or originalControl.Callback,value,window,adapter)
                                end
                            end
                            feature.Controls[#feature.Controls+1]=c
                        end
                    end
                    page.Features[#page.Features+1]=feature
                end
            end
            manifest.Pages[#manifest.Pages+1]=page
        end
    end
    local settings=copy(M.Manifest.Pages[#M.Manifest.Pages]);settings.SharedPreview=true;manifest.Pages[#manifest.Pages+1]=settings
    local ok,result=xpcall(function()
        return M.App(M,{Manifest=manifest,Mobile=profile.Layout=='Mobile',InitialValues=config.Data,ConfigPath='SerenityHub/ui-v3-2-'..tostring(game.GameId)..'.json'})
    end,debug.traceback)
    if not ok then runtime:Destroy('build-failed');error(result,0) end
    window=result
    runtime:TrackCleanup(function()window.Runtime:Destroy()end)
    function window:Destroy()runtime:Destroy('manual')end
    window.Close=window.Destroy
    function window:Minimize()self:SetVisible(false)end
    function window:Restore()self:SetVisible(true)end
    window.Open=window.Restore
    function window:SwitchPage(id)
        for key,entry in pairs(self.Pages)do if key==id or entry.Spec.Title==id then self:SelectPage(key);return true end end
        return false
    end
    local notify=window.Notify
    function window:Notify(title,text)notify(self,text and (tostring(title)..': '..tostring(text)) or title)end
    function window:SetStatus(value)self.Status=tostring(value or '')end
    adapter={Controls=window.Controls,Features=window.Sections,Window=window,Config=config,Runtime=runtime,Manifest=source,Layout=profile.Layout}
    function adapter:SetLive(key,value)
        local item=self.Controls[key];if not item or not item.Set then return false end
        item:Set(value,true);return true
    end
    function adapter:ResetAll()
        for key,value in pairs(defaults)do
            local item=self.Controls[key]
            if item and item.Set then item:Set(copy(value),false) end
            config:Set(key,copy(value),true)
        end
        return config:SaveNow()
    end
    window.Adapter=adapter
    local app={Version='3.2.0',APIVersion=3,Window=window,Config=config,Runtime=runtime,Profile=profile,Manifest=source,Adapter=adapter}
    function app:Destroy()runtime:Destroy('manual')end
    return app
end}



